import * as C from './compare-records-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ratio=x=>typeof x==='number'?{n:x,d:1}:x;
const format=x=>C.formatCompare(ratio(x));
function number(x,signed=false){const r=ratio(x),raw=format(x),visible=r.n<0?raw.replace('-','−'):signed&&r.n>0?'+'+raw:raw,say=(r.n<0?'minus ':signed&&r.n>0?'plus ':'')+format({n:Math.abs(r.n),d:r.d}).replace('/',' over ');return `<span data-cr-number data-cr-say="${esc(say)}">${esc(visible)}</span>`;}
const grams=(x,signed=false)=>`${number(x,signed)} g`;
const diff=(mean,reference)=>C.compareRatio(mean.n-reference*mean.d,mean.d);
const button=(attrs,label,{disabled=false,pressed=null}={})=>`<button type="button" ${attrs}${disabled?' disabled':''}${pressed===null?'':` aria-pressed="${pressed}"`}>${esc(label)}</button>`;
const pages=['Agreement between repeats','A separate adjustment','Try a different reference'];
const referenceVisible=(w,page)=>page===2?w.referenceView.checkShown:w.referenceView.referenceShown;
const stageFor=c=>C.referenceScaleStage(c.work,c.ui.page===2);
function rowAxis(geometry,baseline){return `<line class="cr-axis" x1="60" x2="560" y1="${baseline+18}" y2="${baseline+18}"/>${geometry.ticks.map(t=>`<path class="cr-axis" d="M${t.x} ${baseline+18}v6"/>${t.label?`<text data-rs-tick data-rs-tick-value="${t.value}" x="${t.x}" y="${baseline+60}" text-anchor="middle">${esc(t.value)}</text>`:''}`).join('')}`;}
function highlight(stats,focus,baseline,max){const x=v=>60+500*v/max,y=baseline-12;return focus==='range'?`<path data-rs-highlight="range" d="M${x(stats.min)} ${y}H${x(stats.max)} ${y}M${x(stats.min)} ${y}v8M${x(stats.max)} ${y}v8"/>`:`<line data-rs-highlight="${focus}" x1="${x(C.compareNumber(stats[focus]))}" x2="${x(C.compareNumber(stats[focus]))}" y1="${y}" y2="${baseline+18}"/>`;}
function plot(c){
 const w=c.work,stage=stageFor(c),s=stage.source,g=C.compareGeometry(s),seen=referenceVisible(w,c.ui.page),adjusted=seen&&w.referenceView.adjustmentShown,preview=adjusted?C.referenceScalePreview(w,c.ui.page===2):null,base=g.baselines[1]+g.band,height=g.height+(adjusted?g.band:0),target=g.groups.find(x=>x.id===stage.groupId),label=s.groups.find(x=>x.id===stage.groupId).label;
 let drawing=g.groups.map((group,i)=>`<g class="cr-group-${i}">${rowAxis(g,group.baseline)}${highlight(C.recordSummary(s.groups.find(x=>x.id===group.id).records),w.focus,group.baseline,s.axis.max)}${group.points.map(p=>`<circle data-rs-original data-rs-group="${esc(group.id)}" data-rs-id="${esc(p.id)}" data-rs-value="${p.value}" cx="${p.x}" cy="${p.y}" r="6"><title>${esc(group.label)} · ${esc(p.id)} · ${esc(p.value)} g · original</title></circle>`).join('')}</g>`).join('');
 if(adjusted)drawing+=`<g class="rs-preview-row">${rowAxis(g,base)}${highlight(preview.summary,w.focus,base,s.axis.max)}${target.points.map(p=>{const value=preview.records.find(r=>r.id===p.id).value,x=60+500*value/s.axis.max,y=base-20*p.lane;return `<path data-rs-preview data-rs-group="${esc(stage.groupId)}" data-rs-id="${esc(p.id)}" data-rs-value="${value}" data-rs-x="${x}" data-rs-y="${y}" d="M${x} ${y-8}l8 8-8 8-8-8Z"><title>${esc(label)} · ${esc(p.id)} · ${value} g · adjusted preview</title></path>`;}).join('')}</g>`;
 if(seen){const x=60+500*stage.reference/s.axis.max;drawing+=`<line data-rs-reference-line x1="${x}" x2="${x}" y1="15" y2="${height-40}"/>`;}
 const description=s.groups.map(group=>`${group.label}: ${group.records.map(r=>r.value).join(', ')} grams, original readings.`).join(' ')+(seen?` Model reference ${stage.reference} grams.`:' No model reference has been revealed in this view.')+(adjusted?` Separate preview row for ${label}: ${preview.records.map(r=>r.value).join(', ')} grams.`:'');
 return `<figure class="cr-paper rs-paper"><div class="cr-plot-key">${s.groups.map((group,i)=>`<p><span class="cr-swatch cr-swatch-${i}" aria-hidden="true"></span><strong>Original row ${i+1}: ${esc(group.label)}</strong></p>`).join('')}${adjusted?`<p><span class="rs-diamond-key" aria-hidden="true"></span><strong>Separate preview row: ${esc(label)}</strong></p>`:''}${seen?`<p><span class="rs-reference-key" aria-hidden="true"></span><strong>Model reference: ${grams(stage.reference)}</strong></p>`:''}</div><svg data-rs-plot viewBox="0 0 600 ${height}" role="img" aria-label="${esc(description+' Read grams across the common axis. Vertical stacking only keeps nearby dots apart.')}">${drawing}</svg><figcaption>Each solid dot is one invented reading. Read grams across; stacking only keeps nearby dots apart. All rows use the same horizontal scale, from ${grams(0)} to ${grams(s.axis.max)}, with ${grams(s.axis.tick)} between ticks.</figcaption></figure>`;
}
function summaryTable(c){const w=c.work,stage=stageFor(c),seen=referenceVisible(w,c.ui.page),rows=[['Count','n'],['Mean','mean'],['Median','median'],['Range','range']];return `<table data-rs-summarytable class="cr-summaries"><caption>Original readings · grams; count in readings</caption><thead><tr><th scope="col">Summary</th>${stage.source.groups.map(g=>`<th scope="col">${esc(g.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,key])=>`<tr${w.focus===key?' class="cr-selected-summary"':''}><th scope="row">${label}</th>${stage.source.groups.map(g=>`<td data-rs-summary="${key}" data-rs-group="${esc(g.id)}">${number(C.recordSummary(g.records)[key])}</td>`).join('')}</tr>`).join('')}${seen?`<tr><th scope="row">Mean minus model reference (g)</th>${stage.source.groups.map(g=>`<td>${number(diff(C.recordSummary(g.records).mean,stage.reference),true)}</td>`).join('')}</tr>`:''}</tbody></table>`;}
function adjustedTable(c){const w=c.work,stage=stageFor(c),group=stage.source.groups.find(g=>g.id===stage.groupId),original=C.recordSummary(group.records),preview=C.referenceScalePreview(w,c.ui.page===2).summary;return `<table data-rs-adjustedtable class="cr-summaries"><caption>${esc(group.label)} · separate numerical preview</caption><thead><tr><th scope="col">Summary</th><th scope="col">Original</th><th scope="col">Adjusted preview</th></tr></thead><tbody>${[['Mean','mean'],['Median','median'],['Range','range']].map(([label,key])=>`<tr><th scope="row">${label} (g)</th><td>${number(original[key])}</td><td>${number(preview[key])}</td></tr>`).join('')}<tr><th scope="row">Mean minus reference (g)</th><td>${number(diff(original.mean,stage.reference),true)}</td><td>${number(diff(preview.mean,stage.reference),true)}</td></tr></tbody></table>`;}
function adjustmentControls(c){
 const w=c.work,v=w.referenceView,stage=stageFor(c),bounds=w.source.referenceScales.adjustment,group=stage.source.groups.find(g=>g.id===stage.groupId);if(!referenceVisible(w,c.ui.page))return '';
 if(!v.adjustmentShown)return c.mutable?`<section class="rs-model-controls">${button('data-rs-adjust-start','Try an adjustment')}<p>Add the same number to each ${esc(group.label)} reading in a separate preview.</p></section>`:'';
 return `<section class="rs-model-controls"><h3>Separate preview</h3><p data-rs-adjustment>${esc(group.label)} · adjustment: <strong>${grams(v.adjustment,true)}</strong></p>${c.mutable?`<div class="cr-actions" role="group" aria-label="Adjust every reading of ${esc(group.label)}">${button('data-rs-adjust="-1"','1 g less',{disabled:v.adjustment<=bounds.min})}${button('data-rs-adjust="1"','1 g more',{disabled:v.adjustment>=bounds.max})}${button('data-rs-adjust="reset"','Reset adjustment',{disabled:v.adjustment===0})}</div>`:''}<p class="rs-preview-note">Original solid dots stay fixed.</p></section>`;
}
function adjustmentSummary(c){
 if(!referenceVisible(c.work,c.ui.page)||!c.work.referenceView.adjustmentShown)return '';
 return `<section class="rs-adjustment-summary">${adjustedTable(c)}<details data-rs-limit><summary>What this preview shows</summary><p>Adding the same number to every reading moves the center by that number and leaves the range unchanged. A zero adjustment leaves the readings unchanged.</p><p>${esc(c.work.source.referenceScales.copy.limit)}</p></details><p>A numerical preview changes no real scale.</p></section>`;
}
function referenceBanner(c){const w=c.work,stage=stageFor(c);return referenceVisible(w,c.ui.page)?`<p class="rs-reference-banner">Model reference: <strong>${grams(stage.reference)}</strong>. A matching mean does not make every reading exact.</p>`:c.mutable?`<p>${button('data-rs-reference','Reveal the model reference')}</p>`:'<p>The model reference was not opened in this kept view. Try this comparison again to reveal it.</p>';}
function model(c){
 const adjusted=referenceVisible(c.work,c.ui.page)&&c.work.referenceView.adjustmentShown;
 const summaries=`<h3>Highlight: ${esc(c.work.focus)}</h3>${c.mutable?`<div class="cr-focus" role="group" aria-label="Highlight a summary">${['mean','median','range'].map(id=>button(`data-cr-focus="${id}"`,id[0].toUpperCase()+id.slice(1),{pressed:c.work.focus===id})).join('')}</div>`:''}${c.ui.page===0?summaryTable(c):`<details data-rs-summaries${c.ui.summaryOpen?' open':''}><summary>Original summaries</summary>${summaryTable(c)}</details>`}`;
 return `${referenceBanner(c)}<div class="rs-model-grid">${c.ui.page>0?adjustmentControls(c):''}${plot(c)}<section class="rs-model-summary">${c.ui.page>0&&adjusted?adjustmentSummary(c):''}${summaries}</section></div>${c.ui.page===0&&adjusted?adjustmentSummary(c):''}${workings(c)}`;
}
function formulas(group,stats,reference,label){const middle=Math.floor(stats.n/2);return `<section><h3>${esc(group.label)} · ${esc(label)}</h3><p>Readings: ${stats.ordered.map(r=>number(r.value)).join(', ')} g.</p><p>Total: ${grams(stats.total)}. ${number(stats.total)} ÷ ${number(stats.n)} = ${grams(stats.mean)} per reading.</p><p>${stats.n%2?`The middle value is ${grams(stats.median)}.`:`The two middle values are ${grams(stats.ordered[middle-1].value)} and ${grams(stats.ordered[middle].value)}. (${number(stats.ordered[middle-1].value)} + ${number(stats.ordered[middle].value)}) ÷ 2 = ${grams(stats.median)}.`}</p><p>Range: ${number(stats.max)} − ${number(stats.min)} = ${grams(stats.range)}.</p>${reference===null?'':`<p>Mean minus model reference: ${number(stats.mean)} − ${number(reference)} = ${grams(diff(stats.mean,reference),true)}.</p>`}</section>`;}
function workings(c){const w=c.work,shown=w.workingsShown,stage=stageFor(c),seen=referenceVisible(w,c.ui.page);return `${c.mutable?button('data-cr-workings',shown?'Hide how':'Show how',{pressed:shown}):''}${shown?`<section class="cr-workings"><h3 id="cr-workings-heading" tabindex="-1">Arithmetic from these readings</h3>${stage.source.groups.map(g=>formulas(g,C.recordSummary(g.records),seen?stage.reference:null,'original')).join('')}${seen&&w.referenceView.adjustmentShown?formulas(stage.source.groups.find(g=>g.id===stage.groupId),C.referenceScalePreview(w,c.ui.page===2).summary,stage.reference,'adjusted preview'):''}<p>These calculations are shown for you.</p></section>`:''}`;}
function teaching(c){const helper=C.compareWorked(c.work.source);if(!helper)return '';return `<section class="cr-teaching">${c.mutable||c.work.workedSeen?button('data-cr-worked',c.ui.workedOpen?'Close the different example':'Try a different worked example',{pressed:c.ui.workedOpen}):'<p>The worked example was not opened in this kept comparison. Try it again to open more teaching.</p>'}${c.ui.workedOpen?`<h3 id="cr-teaching-heading" tabindex="-1">Different worked example</h3>${c.mutable?`<p>${esc(helper.steps[c.ui.step])}</p><div class="cr-actions">${button('data-cr-step="-1"','Previous example part',{disabled:c.ui.step===0})}${button('data-cr-step="1"','Next example part',{disabled:c.ui.step===helper.steps.length-1})}</div>`:`<ol>${helper.steps.slice(0,c.work.workedSeen).map(step=>`<li>${esc(step)}</li>`).join('')}</ol>`}`:''}</section>`;}
function sourceFold(c){const w=c.work,available=c.ui.page!==2||w.referenceView.checkShown,stage=C.referenceScaleStage(w,c.ui.page===2&&w.referenceView.checkShown);return `<details data-cr-source-fold${c.ui.sourceOpen?' open':''}><summary>Source and original readings</summary><p>${esc(w.source.origin)}</p><p>${esc(w.source.notice)}</p><p>${esc(w.source.purpose)}</p>${available?`<div class="cr-record-lists">${stage.source.groups.map(g=>`<section><h3>${esc(g.label)} · original</h3><ol>${g.records.map(r=>`<li>${esc(r.id)}: ${grams(r.value)}${r.note?` · ${esc(r.note)}`:''}</li>`).join('')}</ol></section>`).join('')}</div>`:'<p>The check panel has not been opened in this comparison.</p>'}</details>`;}
function glossary(c){return `<details data-rs-glossary${c.ui.glossaryOpen?' open':''}><summary>Words for this comparison</summary><dl>${c.work.source.referenceScales.glossary.map(g=>`<dt>${esc(g.term)}</dt><dd>${esc(g.meaning)}</dd>`).join('')}</dl></details>`;}
// Adult reference interpretation only; never part of the child's current-turn speech.
export const referenceGrownup='This finite model contrasts repeat agreement, sample-mean reference difference and individual readings. Its reference values and readings are stipulated, not verified physical data. Range illustrates spread; it is not a standard deviation, uncertainty interval or instrument rating. A centered sample mean does not certify accuracy, trueness or calibration across a range. No significant-figure, instrument-selection or practical-measurement proficiency is observed. Panel flags retain chosen views, not proof of reading or independent reasoning. The full frozen source remains in Notes. Explanations stay spoken/on paper and human-read; no assessment, story credit or record of a real calibration is created.';
// End adult reference interpretation.
export function referenceScalesPage(c,notice=''){
 const w=c.work;if(!C.validReferenceScaleWork(w))return `<div class="cr-page" data-cr-root><h1>Reference Scales</h1><p>This earlier scale comparison cannot open here. Its original data stays in your Notes download. Other comparisons are open.</p>${button('data-cr-choose','Choose records')}<a href="#notes">Grown-up notes</a><p id="cr-status" role="status">${esc(notice)}</p></div>`;
 const opened=c.ui.page!==2||w.referenceView.checkShown,seen=referenceVisible(w,c.ui.page),stage=opened?stageFor(c):null;const ownCheck=w.source.referenceScales.copy.checkIntro,checkIntro=Object.hasOwn(w.source.referenceScales.copy,'checkIntro')&&typeof ownCheck==='string'&&ownCheck.trim()&&ownCheck.length<=1000?ownCheck:'These new lists repeat a different shared item, again in the same model conditions.';
 const instruction=c.ui.page===0?'Compare the dots and their ranges. Which list agrees more closely? What else would you need to know?':c.ui.page===1?'Change the preview and watch the same-scale drawing.':'Use the same adjustment with a different model example. What do we still not know?';
 return `<div class="cr-page rs-page" data-cr-root${!c.mutable?' data-cr-kept':''}><header><a href="#learn/math">Back to math explorations</a><h1>Reference Scales</h1><p>The Compare Shelf · invented readings, not a real scale calibration.</p></header><section data-cr-turn><h2 id="cr-heading" tabindex="-1">${pages[c.ui.page]}</h2><p class="cr-instruction">${instruction}</p><p class="cr-context">${esc(w.source.title)} · original readings in grams</p>${c.ui.page===0?`<p>${esc(w.source.referenceScales.copy.intro)}</p>`:`<p>${c.ui.page===2&&opened?esc(checkIntro):'Each list repeats one shared model item, in the same conditions.'}</p><details data-rs-about${c.ui.aboutOpen?' open':''}><summary>About this model</summary><p>${esc(w.source.referenceScales.copy.intro)}</p></details>`}<nav class="cr-tabs" aria-label="Scale comparison turns">${pages.map((title,i)=>button(`data-cr-page="${i}"`,title,{pressed:c.ui.page===i})).join('')}</nav>${opened?model(c):`<section class="cr-question"><h3>A different model item</h3>${c.mutable?button('data-rs-check','Open the check example'):'<p>The check panel was not opened in this kept comparison. Try it again to open more.</p>'}</section>`}${c.ui.page===0?teaching(c):''}${c.ui.page===2&&opened?`<p>Two model examples do not show that an adjustment works for every mass or for a real scale.</p><p>${esc(w.source.referenceScales.copy.reflection)}</p><p><a href="#science/measure">Return to the real Measuring Desk</a></p><p>At the real jug, matching entered readings do not prove an exact amount. These model numbers do not calibrate that jug.</p>`:''}${sourceFold(c)}${glossary(c)}<div class="cr-actions cr-main-actions">${button(`data-cr-page="${c.ui.page-1}"`,'Previous',{disabled:c.ui.page===0})}${button(`data-cr-page="${c.ui.page+1}"`,'Next',{disabled:c.ui.page===2})}${c.mutable?button('data-cr-keep','Keep this comparison'):button(`data-cr-again="${esc(c.id)}"`,'Try this comparison again')}${hearButton('','Hear this turn').replace('<button','<button data-cr-hear')}${button('data-cr-choose','Choose records')}</div><p>${c.mutable?'Unkept choices stay in this visit. Keep a comparison before leaving if you want it later.':'This kept comparison stays as it was. Try it again to change a choice or open more teaching.'}</p></section><p id="cr-status" role="status" tabindex="-1" class="cr-status${notice?'':' sr-only'}">${esc(notice)}</p><details class="rs-grownup"><summary>For grown-ups</summary><p>${esc(referenceGrownup)}</p><a href="https://www.itl.nist.gov/div898/handbook/mpc/section1/mpc113.htm" target="_blank" rel="noopener noreferrer">NIST: bias and accuracy</a><a href="https://www.itl.nist.gov/div898/handbook/mpc/section1/mpc114.htm" target="_blank" rel="noopener noreferrer">NIST: variability</a></details><footer><a href="#science/measure">The real Measuring Desk</a><a href="#learn/math">Math explorations</a><a href="#notes">Grown-up notes</a></footer></div>`;
}
